mapper.sql:
from sys_user u
left join sys_dept d on u.dept_id = d.dept_id
where u.del_flag = '0'


    AND u.user_id = #{user.userId}


    AND u.user_name like concat('%', #{user.userName}, '%')


    AND u.status = #{user.status}


    AND u.phonenumber like concat('%', #{user.phoneNumber}, '%')


    AND (u.dept_id = #{user.deptId}
    OR u.dept_id IN (SELECT t.dept_id FROM sys_dept t WHERE find_in_set(#{user.deptId}, ancestors)))

from sys_user u left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0' and r.role_id = #{user.roleId}
AND u.user_name like concat('%', #{user.userName}, '%')
AND u.phonenumber like concat('%', #{user.phoneNumber}, '%')

mapper.select:
select distinct u.user_id, u.dept_id, u.user_name, u.nick_name, u.email, u.phonenumber, u.status

order by u.user_id
limit #{limit} offset #{offset}

select distinct u.user_id, u.dept_id, u.user_name, u.nick_name, u.email, u.phonenumber, u.status

order by u.user_id
limit #{limit} offset #{offset}

mapper.update:
update sys_user
dept_id = #{deptId}, user_name = #{userName}, nick_name = #{nickName}, user_type = #{userType}, email = #{email}, phonenumber = #{phoneNumber}, sex = #{sex}, password = #{password}, status = #{status}, update_by = #{updateBy}, update_time = CURRENT_TIMESTAMP
where user_id = #{userId}
